/* From Uiverse.io by Yaya12085 - Tags: form */
.__UIV_SCOPE__ .form {
  max-width: 320px;
  width: 100%;
  background-color: #fff;
  padding: 20px;
  box-shadow: 0px 0px 0px 4px rgba(52, 52, 53, 0.185);
  display: flex;
  flex-direction: column;
  border-radius: 10px;
}

.__UIV_SCOPE__ .title {
  text-align: center;
  font-size: 2rem;
  margin-bottom: 20px;
  color: #1a202c;
}

.__UIV_SCOPE__ .label {
  color: rgb(0, 0, 0);
  margin-bottom: 4px;
}

.__UIV_SCOPE__ .input {
  padding: 10px;
  margin-bottom: 20px;
  width: 100%;
  font-size: 1rem;
  color: #4a5568;
  outline: none;
  border: 1px solid transparent;
  border-radius: 4px;
  transition: all 0.2s ease-in-out;
}

.__UIV_SCOPE__ .input:focus {
  background-color: #fff;
  box-shadow: 0 0 0 2px #cbd5e0;
}

.__UIV_SCOPE__ .input:valid {
  border: 1px solid green;
}

.__UIV_SCOPE__ .input:invalid {
  border: 1px solid rgba(14, 14, 14, 0.205);
}

.__UIV_SCOPE__ .submit {
  background-color: #1a202c;
  color: #fff;
  border: none;
  border-radius: 4px;
  padding: 10px 20px;
  font-size: 1.2rem;
  cursor: pointer;
  transition: all 0.2s ease-in-out;
}
